package pag.domains.gen;

import pag.api.BinOp;
import pag.api.Domain;
import pag.api.LVal;
import pag.api.MethodId;
import pag.api.RVal;
import pag.api.Step;

public class AbstractDomain implements Domain<S> {
    private final String name;
    private final S topState;
    private final S bottomState;

    public AbstractDomain(String name) {
        this.name = name;
        this.topState = top();
        this.bottomState = bottom();
    }

    @Override
    public String name() {
        return name;
    }

    @Override
    public S top() {
        return topState;
    }

    @Override
    public S bottom() {
        return bottomState;
    }

    @Override
    public boolean isBottom(S s) {
        return s == bottomState;
    }

    @Override
    public boolean entails(S a, S b) {
        return a <= b;
    }

    @Override
    public S join(S a, S b) {
        return a + b;
    }

    @Override
    public S widen(S a, S b) {
        return a + b;
    }

    @Override
    public S transfer(Step step, S post) {
        return step.apply(post);
    }
}
